-- 003: Remember which player created a case, and the idea they typed.
-- Cases written by hand or generated by the admin have created_by = NULL.

-- ON DELETE SET NULL: if a player deletes their account, their cases stay
-- playable; they just lose the "Created by" name.
ALTER TABLE cases ADD COLUMN created_by UUID REFERENCES users(id) ON DELETE SET NULL;

-- The player's own words, kept so the admin can see what led to a case.
ALTER TABLE cases ADD COLUMN player_prompt TEXT
  CHECK (player_prompt IS NULL OR char_length(player_prompt) BETWEEN 1 AND 500);

-- Speeds up "how many cases has this player created today?" (the daily limit).
CREATE INDEX cases_created_by_created_at_idx ON cases (created_by, created_at);
